from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe')
expect='227b00fb0142aa92df0c826f27980b65e2a452ad'
def git(*args):
 return subprocess.run(['git',*args],cwd=repo,text=True,capture_output=True,check=True).stdout.strip()
if git('rev-parse','HEAD')!=expect or git('rev-parse','origin/main')!=expect:raise SystemExit('HEAD_CHANGED')
status=git('status','--short');print('STATUS',status)
allowed={'adapters/protocol.py','do-again.toml','do-again-policy.json','jobctl.py','tests/test_jobctl.py'}
if any(line[3:] not in allowed for line in status.splitlines()):raise SystemExit('UNEXPECTED_DIRTY')
if 'Registration uncertain' not in (repo/'jobctl.py').read_text():raise SystemExit('GUARD_MISSING')
if 'test_apply_csv_explicit_uncertain_status_never_initializes_ats' not in (repo/'tests/test_jobctl.py').read_text():raise SystemExit('REGRESSION_MISSING')
def check(args,sec):
 p=subprocess.Popen([str(repo/'.venv/bin/python'),'-m','pytest','-q','--maxfail=1']+args,cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=sec)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('TIMEOUT',args,o[-1100:]);raise SystemExit(124)
 print('TEST',args,'EXIT',p.returncode,o[-1900:],e[-250:])
 return p.returncode
if check(['tests/test_ats_adapter_contract.py','-k','explicit_confirmation_produces_verified_evidence'],200):raise SystemExit('ASHBY_REPRODUCED_OR_INFRA')
if check(['tests/test_jobctl.py'],100):raise SystemExit('JOBCTL_FAILED')
if check([],640):raise SystemExit('FULL_SUITE_FAILED')
subprocess.run(['git','add','--','jobctl.py','tests/test_jobctl.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','fix: block uncertain Workday registration under status override'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True,timeout=90)
print('VERIFIED_PUSH',git('rev-parse','HEAD'))
